import uuid
from datetime import datetime

from pydantic import BaseModel, ConfigDict, Field

from app.schemas.exercise import ExerciseRead

MEDICAL_NOTICE = (
    "This plan is generated by software and is not medical advice. Talk to a "
    "doctor before starting a new exercise programme."
)

# --- What the LLM must return ----------------------------------------------


class WorkoutExerciseDraft(BaseModel):
    exercise_id: uuid.UUID
    sets: int = Field(ge=1, le=10)
    reps: int = Field(ge=1, le=100)
    rest_seconds: int = Field(ge=0, le=600)


class WorkoutDayDraft(BaseModel):
    focus: str = Field(min_length=1, max_length=100)
    exercises: list[WorkoutExerciseDraft] = Field(min_length=3, max_length=8)


class WorkoutPlanDraft(BaseModel):
    days: list[WorkoutDayDraft] = Field(min_length=1, max_length=7)


# --- What the API returns --------------------------------------------------


class WorkoutPlanExerciseRead(BaseModel):
    model_config = ConfigDict(from_attributes=True)

    position: int
    sets: int
    reps: int
    rest_seconds: int
    exercise: ExerciseRead


class WorkoutPlanDayRead(BaseModel):
    model_config = ConfigDict(from_attributes=True)

    day_index: int
    focus: str
    exercises: list[WorkoutPlanExerciseRead]


class WorkoutPlanSummary(BaseModel):
    model_config = ConfigDict(from_attributes=True)

    id: uuid.UUID
    is_active: bool
    model: str
    created_at: datetime


class WorkoutPlanRead(WorkoutPlanSummary):
    days: list[WorkoutPlanDayRead]
    notice: str = MEDICAL_NOTICE
